	private static void assertContextIDs(HistoryFixture fixture, Set<Resource> expected, boolean selective,
			Set<Resource> expectedSelectiveContexts) throws Exception {
		HistoryBacking backing = fixture.backing;
		int datasetsOpenedBefore = backing.datasetOpenCalls.get();
		int datasetsClosedBefore = backing.datasetCloseCalls.get();
		int contextsOpenedBefore = backing.contextCursorOpenCalls.get();
		int contextsClosedBefore = backing.contextCursorCloseCalls.get();
		int statementsOpenedBefore = backing.statementCursorOpenCalls.get();
		int statementsClosedBefore = backing.statementCursorCloseCalls.get();
		int wildcardOpenedBefore = backing.wildcardStatementCursorOpenCalls.get();
		int requestCountBefore = backing.statementContextRequestCount();

		List<Resource> actual;
		try (SailDataset dataset = fixture.branch.dataset(IsolationLevels.NONE)) {
			actual = readResources(dataset.getContextIDs());
		}

		int datasetOpens = backing.datasetOpenCalls.get() - datasetsOpenedBefore;
		int datasetCloses = backing.datasetCloseCalls.get() - datasetsClosedBefore;
		int contextOpens = backing.contextCursorOpenCalls.get() - contextsOpenedBefore;
		int contextCloses = backing.contextCursorCloseCalls.get() - contextsClosedBefore;
		int statementOpens = backing.statementCursorOpenCalls.get() - statementsOpenedBefore;
		int statementCloses = backing.statementCursorCloseCalls.get() - statementsClosedBefore;
		int wildcardOpens = backing.wildcardStatementCursorOpenCalls.get() - wildcardOpenedBefore;
		List<List<Resource>> contextRequests = backing.statementContextRequestsFrom(requestCountBefore);
		String activation = "actual contexts=" + actual + ", backing context cursors=" + contextOpens + "/"
				+ contextCloses
				+ ", backing statement cursors=" + statementOpens + "/" + statementCloses
				+ ", wildcard statement cursors=" + wildcardOpens + ", selective contexts=" + contextRequests;
		assertThat(actual).as("fixture must return the supported context membership; " + activation)
				.containsExactlyInAnyOrderElementsOf(expected);
		assertAll(
				() -> assertThat(datasetOpens).as("one dataset owner opened; " + activation).isEqualTo(1),
				() -> assertThat(datasetCloses).as("dataset owner disposed once; " + activation).isEqualTo(1),
				() -> assertThat(contextOpens).as("use the backing context cursor once; " + activation).isEqualTo(1),
				() -> assertThat(contextCloses).as("close the backing context cursor once; " + activation).isEqualTo(1),
				() -> assertThat(statementCloses).as("close every backing statement cursor once; " + activation)
						.isEqualTo(statementOpens),
				() -> assertThat(wildcardOpens).as("context enumeration must not scan all statements; " + activation)
						.isZero(),
				() -> {
					if (selective) {
						assertThat(contextRequests).as("statement probes must be context-scoped; " + activation)
								.isNotEmpty()
								.allSatisfy(request -> assertThat(request).isNotEmpty());
						assertThat(contextRequests).as("only changed contexts need existence checks; " + activation)
								.allSatisfy(request -> assertThat(expectedSelectiveContexts).containsAll(request));
					} else {
						assertThat(statementOpens)
								.as("unchanged/approval-only views need no statement scan; " + activation)
								.isZero();
					}
				});
	}

