	@Test
	void serializableHistoryPreservesNamespacesContextsAndSnapshotMetadata() throws Exception {
		try (HistoryFixture fixture = HistoryFixture.create(new TrackingModelFactory());
				SailDataset dataset = fixture.branch.dataset(IsolationLevels.NONE)) {
			assertThat(fixture.successfulGenerations).hasValue(GENERATIONS);

			Function<Value, Value> preparer = dataset.getValuePreparer();
			Function<Value, Value> capturer = dataset.getValueCapturer();
			assertThat(preparer).isSameAs(fixture.backing.valuePreparer);
			assertThat(capturer).isSameAs(fixture.backing.valueCapturer);
			assertThat(preparer.apply(VF.createLiteral("input"))).isEqualTo(VF.createLiteral("prepared:input"));
			assertThat(capturer.apply(VF.createLiteral("input"))).isEqualTo(VF.createLiteral("captured:input"));
			assertThat(dataset.isSnapshotCurrent()).isTrue();
			assertThat(dataset.isSnapshotCompatibleWithCurrentAdmission()).isTrue();
			assertThat(fixture.backing.valuePreparerCalls).hasValue(1);
			assertThat(fixture.backing.valueCapturerCalls).hasValue(1);
			assertThat(fixture.backing.snapshotCurrentCalls.get()).isGreaterThan(0);
			assertThat(fixture.backing.snapshotCompatibilityCalls.get()).isGreaterThan(0);

			for (Map.Entry<String, String> expected : fixture.expectedNamespaces.entrySet()) {
				assertThat(dataset.getNamespace(expected.getKey())).isEqualTo(expected.getValue());
			}
			Map<String, String> namespaces = new LinkedHashMap<>();
			try (CloseableIteration<? extends Namespace> cursor = dataset.getNamespaces()) {
				while (cursor.hasNext()) {
					Namespace namespace = cursor.next();
					namespaces.put(namespace.getPrefix(), namespace.getName());
				}
			}
			assertThat(namespaces).isEqualTo(fixture.expectedNamespaces);
			Set<Resource> expectedContexts = new LinkedHashSet<>();
			for (Statement statement : fixture.expectedStatements) {
				if (statement.getContext() != null) {
					expectedContexts.add(statement.getContext());
				}
			}
			assertThat(readResources(dataset.getContextIDs())).containsExactlyInAnyOrderElementsOf(expectedContexts);
		}
	}

